```python
# Define the game world as a dictionary
game_world = {
    "start": {
        "description": "You are in a dark room. There is a door to the north.",
        "actions": ["go north"]
    },
    "north": {
        "description": "You are now in a dark room. There is a door to the east.",
        "actions": ["go east"]
    },
    "east": {
        "description": "You are now in a dark room. There is a door to the west.",
        "actions": ["go west"]
    },
    "west": {
        "description": "You are now in a dark room. There is a door to the east.",
        "actions": ["go east"]
    }
}

# Function to handle user input
def get_user_input():
    while True:
        user_input = input("Enter your command: ")
        if user_input.lower() in game_world[current_room]["actions"]:
            current_room = game_world[current_room][user_input.lower()]
            return current_room
        else:
